mapper.select:
SELECT * FROM (
    SELECT * FROM messages



                target_id = #{targetId}
                AND is_group = 1


                is_group = 0
                AND (
                    (sender_id = #{currentUserId} AND target_id = #{targetId})
                    OR
                    (sender_id = #{targetId} AND target_id = #{currentUserId})
                )



            AND id < #{beforeId}


    ORDER BY create_time DESC
    LIMIT #{pageSize}
) sub
ORDER BY sub.create_time ASC
